std::vector<int> data = {1, 2, 3, 4, 5};

// Reverse: in-place order change
std::reverse(data.begin(), data.end());

// Rotate: Cyclic shift (Pivot points to new front)
auto pivot = data.begin() + 2;
std::rotate(data.begin(), pivot, data.end());

// Shuffle: Requires a random engine
std::default_random_engine eng;
std::shuffle(data.begin(), data.end(), eng);

// Partition: Group based on predicate (True results first)
std::vector<int> mixed = {1, 6, 3, 8, 5};
auto bound = std::partition(
    mixed.begin(), mixed.end(),
    [](int n){ return n % 2 != 0; }
);
